  ctx.fillStyle = color;
  ctx.font = `${size}px sans-serif`;
  ctx.textBaseline = 'top';
  ctx.fillText(text, x, y);
}

function drawBox(x, y, w, h) {
  ctx.strokeStyle = colors.box;
  ctx.lineWidth = 2;
  ctx.strokeRect(x, y, w, h);
  ctx.fillStyle = colors.boxBg;
  ctx.fillRect(x, y, w, h);
}

function drawArrow(x1, y1, x2, y2) {
  ctx.strokeStyle = colors.arrow;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  // arrowhead
  const angle = Math.atan2(y2 - y1, x2 - x1);
  const headLength = 10;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - headLength * Math.cos(angle - Math.PI / 6), y2 - headLength * Math.sin(angle - Math.PI / 6));
  ctx.lineTo(x2 - headLength * Math.cos(angle + Math.PI / 6), y2 - headLength * Math.sin(angle + Math.PI / 6));
  ctx.closePath();
  ctx.fillStyle = colors.arrow;
  ctx.fill();
}

function drawExpandedForm() {
  const startX = padding;
  let y = padding + lineHeight;
  drawText('面积式：', startX, y);
  y += lineHeight;
  drawText('A = x² + 6x + 5', startX + 20, y);
  y += lineHeight * 1.5;
  drawText('配方：', startX, y);
  y += lineHeight;
  drawText('A = (x² + 6x + 9) - 9 + 5', startX + 20, y);
  y += lineHeight;
  drawText('A = (x + 3)² - 4', startX + 20, y);
}

function drawCompletedSquare() {
  const startX = padding;
  let y = padding + lineHeight;
  drawText('配方后：', startX, y);
  y += lineHeight;
  drawText('A = (x + 3)² - 4', startX + 20, y);
