  drawText('平方项：', startX, y);
  y += lineHeight;
  drawText('(x + 3)² ≥ 0', startX + 20, y);
  y += lineHeight;
  drawText('所以 A ≥ -4', startX + 20, y);
  y += lineHeight;
  drawText('最小值 -4 当 x = -3', startX + 20, y);
}

function drawNonnegativeHighlight() {
  const startX = padding;
  let y = padding + lineHeight;
  drawText('配方后：', startX, y);
  y += lineHeight;
  drawText('A = (x + 3)² - 4', startX + 20, y);
  y += lineHeight * 1.5;
  drawText('平方项非负：', startX, y);
  y += lineHeight;
  const textX = startX + 20;
  const textY = y;
  const text = '(x + 3)² ≥ 0';
  const textWidth = ctx.measureText(text).width;
  drawText(text, textX, textY, colors.highlight);
  drawBox(textX - 4, textY - 2, textWidth + 8, fontSize + 4);
  y += lineHeight;
  drawText('所以 A ≤ -4', startX + 20, y);
  y += lineHeight;
  drawText('最大值 -4 当 x = -3', startX + 20, y);
