function drawLayoutMeasurement() {
  // emit interaction/layout_measurement
  api.interaction.emit({
    type: 'layout_measurement',
    viewport: { width, height },
    elements: [
      { id: 'expanded-form', bounds: { x: 0, y: 0, width, height } },
