function drawAxes() {
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(50, height/2);
  ctx.lineTo(width-50, height/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(50, 50);
  ctx.lineTo(50, height-50);
  ctx.stroke();
}

function drawWaveform(amplitude, frequency, phase, color, yOffset) {
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.beginPath();
  const startX = 50;
  const endX = width-50;
  const period = (endX - startX) / (2 * Math.PI * frequency);
  for (let x = startX; x <= endX; x++) {
    const t = (x - startX) / period;
    const y = yOffset + amplitude * Math.sin(t + phase);
    if (x === startX) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }
  ctx.stroke();
}

function drawMeasureGuides(amplitude1, amplitude2, yOffset1, yOffset2) {
  ctx.strokeStyle = '#888';
  ctx.lineWidth = 1;
  ctx.setLineDash([5, 5]);
  const xPos = width - 100;
  ctx.beginPath();
  ctx.moveTo(xPos, yOffset1 - amplitude1);
  ctx.lineTo(xPos, yOffset1 + amplitude1);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(xPos + 20, yOffset2 - amplitude2);
  ctx.lineTo(xPos + 20, yOffset2 + amplitude2);
  ctx.stroke();
  ctx.setLineDash([]);
}

