    { element_id: 'waveform2', bounds: { x: 50, y: yOffset2 - amp2, width: width-100, height: 2*amp2 }, font_size: 0, min_graphic_size: 2, interactive: false, touch_size: 0, local_safe_region: 'center' },
    { element_id: 'guide1', bounds: { x: width-101, y: yOffset1 - amp1, width: 2, height: 2*amp1 }, font_size: 0, min_graphic_size: 2, interactive: false, touch_size: 0, local_safe_region: 'center' },
    { element_id: 'guide2', bounds: { x: width-81, y: yOffset2 - amp2, width: 2, height: 2*amp2 }, font_size: 0, min_graphic_size: 2, interactive: false, touch_size: 0, local_safe_region: 'center' },
