function drawScene(state) {
  const canvas = api.canvas;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;
  const params = input.parameters;
  const viewport = params.viewport;
  const layoutMode = viewport.kind;
  const isPhone = layoutMode === 'phone';
  const isTablet = layoutMode === 'tablet';
  const isReducedMotion = state === 'reduced_motion';
  const isStaticFallback = state === 'static_fallback';
  const isInitial = state === 'initial';
  const isKeyProcess = state === 'key_process';
  const isFinal = state === 'final';
  const isPaused = state === 'paused';
  const isResumed = state === 'resumed';
  const isPostInteraction = state === 'post_interaction';

  ctx.clearRect(0, 0, width, height);

  const bgColor = '#F5F5F5';
  const axisColor = '#333333';
  const waveColorBefore = '#1f77b4';
  const waveColorAfter = '#ff7f0e';
  const labelColor = '#333333';
  const annotationColor = '#d62728';
  const gridColor = '#e0e0e0';

  const margin = isPhone ? 20 : 40;
  const plotLeft = margin * 2;
  const plotRight = width - margin;
  const plotTop = margin * 2;
  const plotBottom = height - margin * 3;
  const plotWidth = plotRight - plotLeft;
  const plotHeight = plotBottom - plotTop;

  const amplitudeBefore = 0.3;
  const amplitudeAfter = 0.6;
  const frequency = 2;
  const numPoints = 200;

  function mapX(t) {
    return plotLeft + t * plotWidth;
  }

  function mapY(val) {
    return plotTop + plotHeight / 2 - val * (plotHeight / 2);
  }

  ctx.fillStyle = bgColor;
  ctx.fillRect(0, 0, width, height);

  ctx.strokeStyle = gridColor;
  ctx.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
    const y = plotTop + (i / 4) * plotHeight;
    ctx.beginPath();
    ctx.moveTo(plotLeft, y);
    ctx.lineTo(plotRight, y);
    ctx.stroke();
  }
  for (let i = 0; i <= 4; i++) {
    const x = plotLeft + (i / 4) * plotWidth;
    ctx.beginPath();
    ctx.moveTo(x, plotTop);
    ctx.lineTo(x, plotBottom);
    ctx.stroke();
  }

  ctx.strokeStyle = axisColor;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(plotLeft, plotTop + plotHeight / 2);
  ctx.lineTo(plotRight, plotTop + plotHeight / 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(plotLeft, plotTop);
  ctx.lineTo(plotLeft, plotBottom);
  ctx.stroke();

  ctx.strokeStyle = waveColorBefore;
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (let i = 0; i <= numPoints; i++) {
    const t = i / numPoints;
    const x = mapX(t);
    const y = mapY(amplitudeBefore * Math.sin(2 * Math.PI * frequency * t));
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();

  if (!isInitial && !isStaticFallback) {
    ctx.strokeStyle = waveColorAfter;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i <= numPoints; i++) {
      const t = i / numPoints;
      const x = mapX(t);
      const y = mapY(amplitudeAfter * Math.sin(2 * Math.PI * frequency * t));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  function drawAmplitudeIndicator(amplitude, color, label, xOffset) {
    const yCenter = plotTop + plotHeight / 2;
    const yTop = yCenter - amplitude * (plotHeight / 2);
    const yBottom = yCenter + amplitude * (plotHeight / 2);
    const xPos = plotLeft + xOffset;
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(xPos, yTop);
    ctx.lineTo(xPos, yBottom);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath();
    ctx.moveTo(xPos - 5, yTop + 5);
    ctx.lineTo(xPos, yTop);
    ctx.lineTo(xPos + 5, yTop + 5);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(xPos - 5, yBottom - 5);
    ctx.lineTo(xPos, yBottom);
    ctx.lineTo(xPos + 5, yBottom - 5);
    ctx.stroke();
    ctx.fillStyle = labelColor;
    ctx.font = isPhone ? '10px sans-serif' : '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(label, xPos, yTop - 5);
  }

  if (!isInitial && !isStaticFallback) {
    drawAmplitudeIndicator(amplitudeBefore, waveColorBefore, '振幅小', plotWidth * 0.2);
    drawAmplitudeIndicator(amplitudeAfter, waveColorAfter, '振幅大', plotWidth * 0.8);
  } else {
    drawAmplitudeIndicator(amplitudeBefore, waveColorBefore, '振幅', plotWidth * 0.5);
  }

  function drawPeriodIndicator() {
    const period = 1 / frequency;
    const xStart = mapX(0);
    const xEnd = mapX(period);
    const yPos = plotBottom + 15;
    ctx.strokeStyle = annotationColor;
    ctx.lineWidth = 1;
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.moveTo(xStart, yPos);
    ctx.lineTo(xEnd, yPos);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.beginPath();
    ctx.moveTo(xStart + 5, yPos - 5);
    ctx.lineTo(xStart, yPos);
    ctx.lineTo(xStart + 5, yPos + 5);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(xEnd - 5, yPos - 5);
    ctx.lineTo(xEnd, yPos);
    ctx.lineTo(xEnd - 5, yPos + 5);
    ctx.stroke();
    ctx.fillStyle = labelColor;
    ctx.font = isPhone ? '10px sans-serif' : '12px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('周期不变', (xStart + xEnd) / 2, yPos + 15);
  }

  if (!isInitial && !isStaticFallback) {
    drawPeriodIndicator();
  }

  ctx.fillStyle = labelColor;
  ctx.font = isPhone ? '12px sans-serif' : '14px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('时间', plotLeft + plotWidth / 2, plotBottom + 30);
  ctx.save();
  ctx.translate(plotLeft - 15, plotTop + plotHeight / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('位移', 0, 0);
  ctx.restore();

  const legendX = plotRight - 80;
  const legendY = plotTop + 10;
  ctx.font = isPhone ? '10px sans-serif' : '12px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillStyle = waveColorBefore;
  ctx.fillRect(legendX, legendY, 10, 10);
  ctx.fillStyle = labelColor;
  ctx.fillText('驱动力小', legendX + 15, legendY + 10);
  if (!isInitial && !isStaticFallback) {
    ctx.fillStyle = waveColorAfter;
    ctx.fillRect(legendX, legendY + 20, 10, 10);
    ctx.fillStyle = labelColor;
    ctx.fillText('驱动力大', legendX + 15, legendY + 30);
  }

  if (isStaticFallback) {
    ctx.fillStyle = '#000';
    ctx.font = isPhone ? '12px sans-serif' : '14px sans-serif';
    ctx.textAlign = 'center';
    const fallbackSteps = input.parameters.static_fallback.steps;
    fallbackSteps.forEach((step, index) => {
      ctx.fillText(step, width / 2, plotBottom + 50 + index * 20);
    });
  }

  const elements = [];
  elements.push({
    element_id: 'plot_area',
    bounds: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight },
    font_size: 0,
    min_graphic_size: 0,
    interactive: false,
    touch_size: 0,
    local_safe_region: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight }
  });
  elements.push({
    element_id: 'wave_before',
    bounds: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight },
    font_size: 0,
    min_graphic_size: 2,
    interactive: false,
    touch_size: 0,
    local_safe_region: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight }
  });
  if (!isInitial && !isStaticFallback) {
    elements.push({
      element_id: 'wave_after',
      bounds: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight },
      font_size: 0,
      min_graphic_size: 2,
      interactive: false,
      touch_size: 0,
      local_safe_region: { x: plotLeft, y: plotTop, width: plotWidth, height: plotHeight }
    });
  }
  if (!isInitial && !isStaticFallback) {
    elements.push({
      element_id: 'amplitude_before',
      bounds: { x: plotLeft + plotWidth * 0.2 - 5, y: plotTop, width: 10, height: plotHeight },
      font_size: isPhone ? 10 : 12,
      min_graphic_size: 1,
      interactive: false,
      touch_size: 0,
      local_safe_region: { x: plotLeft + plotWidth * 0.2 - 5, y: plotTop, width: 10, height: plotHeight }
    });
    elements.push({
      element_id: 'amplitude_after',
      bounds: { x: plotLeft + plotWidth * 0.8 - 5, y: plotTop, width: 10, height: plotHeight },
      font_size: isPhone ? 10 : 12,
      min_graphic_size: 1,
      interactive: false,
      touch_size: 0,
      local_safe_region: { x: plotLeft + plotWidth * 0.8 - 5, y: plotTop, width: 10, height: plotHeight }
    });
  } else {
    elements.push({
      element_id: 'amplitude_single',
      bounds: { x: plotLeft + plotWidth * 0.5 - 5, y: plotTop, width: 10, height: plotHeight },
      font_size: isPhone ? 10 : 12,
      min_graphic_size: 1,
      interactive: false,
      touch_size: 0,
      local_safe_region: { x: plotLeft + plotWidth * 0.5 - 5, y: plotTop, width: 10, height: plotHeight }
    });
  }
  if (!isInitial && !isStaticFallback) {
    const period = 1 / frequency;
    const xStart = mapX(0);
    const xEnd = mapX(period);
    elements.push({
      element_id: 'period_indicator',
      bounds: { x: xStart, y: plotBottom + 10, width: xEnd - xStart, height: 20 },
      font_size: isPhone ? 10 : 12,
      min_graphic_size: 1,
      interactive: false,
      touch_size: 0,
      local_safe_region: { x: xStart, y: plotBottom + 10, width: xEnd - xStart, height: 20 }
    });
  }
  elements.push({
    element_id: 'legend',
    bounds: { x: legendX, y: legendY, width: 80, height: isInitial || isStaticFallback ? 15 : 35 },
    font_size: isPhone ? 10 : 12,
    min_graphic_size: 10,
    interactive: false,
    touch_size: 0,
    local_safe_region: { x: legendX, y: legendY, width: 80, height: isInitial || isStaticFallback ? 15 : 35 }
  });
  elements.push({
    element_id: 'x_label',
    bounds: { x: plotLeft, y: plotBottom + 20, width: plotWidth, height: 20 },
    font_size: isPhone ? 12 : 14,
    min_graphic_size: 0,
    interactive: false,
    touch_size: 0,
    local_safe_region: { x: plotLeft, y: plotBottom + 20, width: plotWidth, height: 20 }
  });
  elements.push({
    element_id: 'y_label',
    bounds: { x: plotLeft - 30, y: plotTop, width: 20, height: plotHeight },
    font_size: isPhone ? 12 : 14,
    min_graphic_size: 0,
    interactive: false,
    touch_size: 0,
    local_safe_region: { x: plotLeft - 30, y: plotTop, width: 20, height: plotHeight }
  });

  api.emit('interaction', {
    type: 'layout_measurement',
    layout_mode: layoutMode,
    canvas_inner_bounds: { x: 0, y: 0, width: width, height: height },
    local_safe_regions: [{ x: 0, y: 0, width: width, height: height }],
    readability_limits: { min_font_size: 10, max_font_size: 14 },
    container_metrics: { width: width, height: height },
    elements: elements,
    motion_envelopes: []
  });

  api.emit('render_complete');
}

drawScene(input.parameters.state);
